#include <bits/stdc++.h>
using namespace std;

void apply_op(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-1-y] [n-y..n-1] -> [n-y..n-1] [x..n-1-y] [0..x-1]
    vector<int> np;
    for (int i = n-y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n-y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    for(int placed = 0; placed < n-2 && (int)ops.size() < 4*n; placed++){
        // Find where value (placed+1) currently is
        int pos = -1;
        for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
        if(pos == placed) continue;

        // Step 1: Move element from pos to position (n-1)
        // We want to make p[pos] end up at the last position
        // Use x = pos+1, y = n-1-pos: this takes prefix [0..pos] and suffix [pos+1..n-1]
        // Result: [suffix | (empty middle) | prefix] but we need x+y < n, i.e., middle non-empty
        // x+y = pos+1 + n-1-pos = n, so middle is empty. Not valid when pos is at n-1 already or middle=0.

        if(pos != n-1) {
            // Use x=pos+1, y=n-1-pos. But x+y=n, invalid.
            // Instead: x=1, y=n-1-pos. x+y = n-pos. Middle = [1..pos]. Need n-pos < n => pos>0.
            // After: [p[pos+1]..p[n-1]] [p[1]..p[pos]] [p[0]]
            // Element at pos moves to position: in middle segment [1..pos], element was at index pos,
            // so in new array it's at (n-1-pos-1) + (pos - 1 + 1) = n-1-pos + pos -1 ... let me just simulate.

            // Strategy: move element to end by: x = pos - placed, y = n - 1 - pos
            // if pos > placed and pos < n-1: middle = [0..placed-1, pos+1-but wait, no]
            // Simpler: x = pos+1, y = n-1-pos-1 = n-2-pos. x+y=pos+1+n-2-pos=n-1 < n. Valid if y>0 => pos<n-2.
            if(pos < n-2) {
                // After: [p[n-2-pos+pos+1=last n-2-pos]..p[n-1]] [p[pos+1]..p[n-2-pos+pos=?]] [p[0]..p[pos]]
                // Element at pos goes to end of new array at position n-1-(pos+1)+pos+1-1 = ... just apply
                int x = pos+1, y = n-2-pos;
                ops.push_back({x, y});
                apply_op(p, x, y);
                // Find element again
                for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            }
            if(pos != n-1 && pos > 0) {
                int x = 1, y = n-1-pos;
                if(x>0 && y>0 && x+y<n) {
                    ops.push_back({x, y});
                    apply_op(p, x, y);
                    for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
                }
            }
        }
        if(pos == placed) continue;
        // Now place element from pos to position 'placed'
        // x = placed, y = n - pos. But if placed==0, x=0 invalid. Use x=1 hack if needed.
        if(placed > 0 && n-pos > 0 && placed + n - pos < n) {
            ops.push_back({placed, n-pos});
            apply_op(p, placed, n-pos);
        } else if(placed == 0 && pos == n-1) {
            ops.push_back({1, 1});
            apply_op(p, 1, 1);
            for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
            if(pos != 0 && pos > 0) {
                int x2=1, y2=n-pos;
                if(x2+y2<n && y2>0){ ops.push_back({x2,y2}); apply_op(p,x2,y2); }
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
